{
  "name": "builder_all_pairs_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap so pairwise labels reflect clearer preference signal and reduce noisy/ambiguous comparisons.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # objective lower is better: i preferred over j when objective[i] + gap <= objective[j]\n    gap = extra.get('gap_threshold', 0.0)\n    diff = objective[:, None, :] - objective[:, :, None]\n    mask = diff >= gap\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_threshold', 'gap_threshold': float(gap)})\n"
}

{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "All objective-improving pairs are kept, but pairs with tiny objective differences can be noisy; adding a configurable nonnegative weight proportional to the objective gap emphasizes clearer preferences while retaining full coverage.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Build all winner/loser pairs where winner has strictly lower objective.\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Nonnegative weight based on objective gap to emphasize clearer preferences.\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_floor = extra.get('gap_floor', 0.0)\n    gap_scale = extra.get('gap_scale', 1.0)\n    weight = (gap - gap_floor).clamp(min=0.0) / (gap_scale + 1e-12)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_floor': float(gap_floor), 'gap_scale': float(gap_scale)})\n"
}

