    lpw = batch.get('log_prob_w', None)
    lpl = batch.get('log_prob_l', None)
    if lpw is None or lpl is None:
        lpw = batch.get('logits_w', batch.get('score_w', None))
        lpl = batch.get('logits_l', batch.get('score_l', None))

    # If required signals are missing, return a stable zero scalar (no crash).
    if lpw is None or lpl is None:
        # Try to anchor dtype/device to any available tensor.
        anchor = None
        if isinstance(model_output, dict):
            for k in ['loss', 'logits', 'scores', 'log_prob']:
                v = model_output.get(k, None)
                if v is not None:
                    anchor = v
                    break
        if anchor is None:
            # Last resort: attempt to find any tensor-like value in batch.
            for v in batch.values():
                anchor = v
                break
        if anchor is None:
            return ops.zeros(())
        return ops.zeros((), dtype=anchor.dtype, device=anchor.device)

    weight = batch.get('weight', None)

    alpha = extra.get('alpha', None)
    if alpha is None:
        alpha = extra.get('hyperparams', {}).get('alpha', 1.0)
    alpha = float(alpha)

    h = extra.get('hyperparams', {})
    scale = float(h.get('scale', 0.5243135399910347))
    cmin = float(h.get('clamp_min', -20.0))
    cmax = float(h.get('clamp_max', 20.0))

    d = alpha * scale * (lpw - lpl)
    d = ops.clamp(d, cmin, cmax)
    loss = -ops.logsigmoid(d)

    if weight is not None:
        # Ensure nonnegative weights; also avoid NaNs from inf weights.
        w = ops.clamp(weight, 0.0, 1.0e6)
        loss = loss * w

    # Mean over batch/pairs.
    return loss.mean()",
