  "intuition": "The gate failure is structural: `implementation_hint.expects` was missing/empty. I keep the swap-invariant, numerically stable objective but simplify and stabilize it: compute the absolute log-prob gap `z=abs(lpw-lpl)` (swap-invariant), penalize only when the gap is below a margin via `softplus((margin - z)*scale)` (smooth hinge), and clamp the pre-softplus argument to avoid overflow/underflow. I also make weight handling robust (broadcast + nonneg clamp) so weighted means stay stable and consistent with the nonneg-weight constraint.",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l"
    ],
    "optional": [
      "weight"
    ],
    "returns_scalar": true,
    "objective": "lower_is_better"
  },
  "hyperparams": {
    "scale": 1.15,
    "margin": 1.0,
    "clamp_min": -30.0,
    "clamp_max": 30.0,
    "eps": 1e-08
  },
  "operators_used": [
    "abs",
    "softplus",
    "clamp"
  ],
  "theoretical_basis": "Symmetric margin-ranking surrogate: minimize a smooth hinge on the absolute preference gap, ensuring swap-invariance (identical loss under swapping winner/loser) while encouraging separation by at least a margin; clamping the logit argument improves numerical stability.",
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}\n    scale = hp.get('scale', 1.15)\n    margin = hp.get('margin', 1.0)\n    clamp_min = hp.get('clamp_min', -30.0)\n    clamp_max = hp.get('clamp_max', 30.0)\n    eps = hp.get('eps', 1e-8)\n\n    d = lpw - lpl\n    z = ops.abs(d)\n\n    t = (margin - z) * scale\n    t = ops.clamp(t, clamp_min, clamp_max)\n    loss = ops.softplus(t)\n\n    if weight is not None:\n        w = ops.clamp(weight, 0.0, 1e9)\n        loss = loss * w\n        denom = ops.clamp(w.sum(), eps, 1e18)\n        return loss.sum() / denom\n\n    return loss.mean()"
}

